// swift-tools-version: 5.9
//
// A test harness for the module's CONVENTION MATHS, and nothing else.
//
// `ios/ARJigCore.swift` imports only Foundation and simd - ARKit appears in its
// comments but never in its code - so the gravity conversion, the angle
// conventions and the gate thresholds are all platform-portable and can be
// tested with `swift test` on a Mac: no simulator, no Expo prebuild, no
// CocoaPods.
//
// Why not an Xcode test target, which is the obvious answer:
//
//   * `apps/mobile/ios` is generated by Expo prebuild and ignored by
//     `apps/mobile/.gitignore` (`/ios`), so a test target placed there is erased
//     by the next clean build and is never committed. A regression shield that
//     evaporates is not a shield.
//   * A CocoaPods `test_spec` in ARJig.podspec is not enough on its own:
//     CocoaPods only installs test specs when the Podfile opts in per-pod with
//     `:testspecs => [...]`, and that Podfile is itself generated and ignored.
//
// This package deliberately builds ONLY ARJigCore.swift. The engine, the view
// and the Expo module really do need ARKit, RealityKit and ExpoModulesCore, and
// they are exercised by the `xcodebuild -scheme ARJig` build instead.
//
//   swift test --package-path apps/mobile/modules/ar-jig
import PackageDescription

let package = Package(
    name: "ARJigCore",
    targets: [
        .target(
            name: "ARJigCore",
            path: "ios",
            // Everything except the one portable file. These three need ARKit,
            // RealityKit or ExpoModulesCore and cannot build for macOS.
            exclude: [
                "ARJig.podspec",
                "ARJigEngine.swift",
                "ARJigModule.swift",
                "ARJigView.swift",
                "ARJigDepthWriter.swift",
                "Tests",
            ],
            sources: ["ARJigCore.swift"]
        ),
        .testTarget(
            name: "ARJigCoreTests",
            dependencies: ["ARJigCore"],
            path: "ios/Tests"
        ),
    ]
)
